268	bool encode_to_der(X509* cert, std::vector<unsigned char>& der) {
269	    int length = i2d_X509(cert, nullptr);
270	    if (length <= 0) return false;
271	    der.resize(static_cast<size_t>(length));
272	    unsigned char* pointer = der.data();
273	    int encoded = i2d_X509(cert, &pointer);
274	    return encoded == length &&
275	           pointer == der.data() + der.size();
276	}
