305	// Reads the whole regular file into contents. Only a complete read that
306	// reaches end of file is a success: a directory, a non-regular file type, a
307	// partial read followed by an error, or any open/stat failure all return a
308	// read error message. errno is captured immediately after the failing call so
309	// the reason always belongs to this operation (never a stale "Success").
310	bool read_file_contents(const std::string& path, std::string& contents,
311	                        std::string& error) {
312	    int fd = open(path.c_str(), O_RDONLY);
313	    if (fd < 0) {
314	        int saved_errno = errno;
315	        error = std::strerror(saved_errno);
316	        return false;
317	    }
318	
319	    struct stat status {};
320	    if (fstat(fd, &status) != 0) {
321	        int saved_errno = errno;
322	        close(fd);
323	        error = std::strerror(saved_errno);
324	        return false;
325	    }
326	    if (S_ISDIR(status.st_mode)) {
327	        close(fd);
328	        error = "is a directory; a certificate file cannot be a directory";
329	        return false;
330	    }
331	
332	    contents.clear();
333	    if (status.st_size > 0) {
334	        contents.reserve(static_cast<size_t>(status.st_size));
335	    }
336	    char buffer[65536];
337	    while (true) {
338	        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
339	        if (bytes_read > 0) {
340	            contents.append(buffer, static_cast<size_t>(bytes_read));
341	        } else if (bytes_read == 0) {
342	            break;  // end of file reached after a complete read
343	        } else if (errno != EINTR) {
344	            int saved_errno = errno;
345	            close(fd);
346	            contents.clear();
347	            error = std::strerror(saved_errno);
348	            return false;
349	        }
350	    }
351	
352	    if (close(fd) != 0) {
353	        int saved_errno = errno;
354	        contents.clear();
355	        error = std::strerror(saved_errno);
356	        return false;
357	    }
358	    return true;
359	}
