361	int inspect_file(const std::string& path) {
362	    std::string content;
363	    std::string read_error;
364	    if (!read_file_contents(path, content, read_error)) {
365	        std::cerr << "trustpeek: failed to read file '" << path
366	                  << "': " << read_error << '\n';
367	        return 1;
368	    }
369	
370	    if (content.empty()) {
371	        std::cerr << "trustpeek: invalid certificate in '" << path
372	                  << "': empty file\n";
373	        return 1;
374	    }
375	
376	    // The encoding is decided by what actually parses, never by the file
377	    // extension and never by marker-like text inside the certificate itself
378	    // (a subject name may legitimately contain "-----BEGIN CERTIFICATE-----").
379	    //
380	    // A DER certificate starts with a SEQUENCE tag (0x30), which no PEM file
381	    // can start with, so the two formats cannot be confused: try DER first
382	    // and require the certificate to occupy the entire file.
383	    const auto* const der_begin =
384	        reinterpret_cast<const unsigned char*>(content.data());
385	    const auto* const der_end = der_begin + content.size();
386	    const unsigned char* pointer = der_begin;
387	
388	    X509Ptr cert(d2i_X509(nullptr, &pointer,
389	                          static_cast<long>(content.size())),
390	                 X509_free);
391	    bool is_pem = false;
392	
393	    if (cert) {
394	        if (pointer != der_end) {
395	            std::cerr << "trustpeek: invalid certificate in '" << path
396	                      << "': trailing bytes after DER certificate\n";
397	            return 1;
398	        }
399	    } else {
400	        BioPtr bio(BIO_new_mem_buf(content.data(),
401	                                  static_cast<int>(content.size())),
402	                   BIO_free_all);
403	        if (!bio) {
404	            std::cerr << "trustpeek: internal error while reading '" << path
405	                      << "'\n";
406	            return 1;
407	        }
408	        cert.reset(PEM_read_bio_X509(bio.get(), nullptr, nullptr, nullptr));
409	        if (!cert) {
410	            // The marker search below only picks the diagnostic wording;
411	            // acceptance is always decided by the parse results above.
412	            if (content.find(kPemBegin) != std::string::npos) {
413	                std::cerr << "trustpeek: invalid certificate in '" << path
414	                          << "': PEM certificate block is malformed or "
415	                             "truncated\n";
416	            } else {
417	                std::cerr << "trustpeek: invalid certificate in '" << path
418	                          << "': DER certificate is malformed or truncated\n";
419	            }
420	            return 1;
421	        }
422	        is_pem = true;
423	    }
424	
425	    std::vector<unsigned char> der;
426	    if (!encode_to_der(cert.get(), der)) {
427	        std::cerr << "trustpeek: invalid certificate in '" << path
428	                  << "': failed to re-encode certificate\n";
429	        return 1;
430	    }
431	
432	    if (is_pem && !validate_single_pem(content, der)) {
433	        std::cerr << "trustpeek: invalid certificate in '" << path
434	                  << "': expected exactly one PEM certificate block with no "
435	                     "other non-whitespace content\n";
436	        return 1;
437	    }
438	
439	    const char* encoding_name = is_pem ? "PEM" : "DER";
440	
441	    std::string subject;
442	    std::string issuer;
443	    std::string not_before;
444	    std::string not_after;
445	    if (!format_name(X509_get_subject_name(cert.get()), subject) ||
446	        !format_name(X509_get_issuer_name(cert.get()), issuer) ||
447	        !format_time(X509_get0_notBefore(cert.get()), not_before) ||
448	        !format_time(X509_get0_notAfter(cert.get()), not_after)) {
449	        std::cerr << "trustpeek: invalid certificate in '" << path
450	                  << "': failed to parse certificate fields\n";
451	        return 1;
452	    }
453	
454	    unsigned char digest[EVP_MAX_MD_SIZE];
455	    size_t digest_length = 0;
456	    if (EVP_Q_digest(nullptr, "SHA256", nullptr, der.data(), der.size(), digest,
457	                     &digest_length) != 1) {
458	        std::cerr << "trustpeek: internal error while hashing '" << path
459	                  << "'\n";
460	        return 1;
461	    }
462	
463	    std::ostringstream output;
464	    output << "Encoding: " << encoding_name << '\n'
465	           << "Subject: " << subject << '\n'
466	           << "Issuer: " << issuer << '\n'
467	           << "Not Before: " << not_before << '\n'
468	           << "Not After: " << not_after << '\n'
469	           << "SHA-256 Fingerprint: "
470	           << format_fingerprint(digest, digest_length) << '\n'
471	           << "Note: this output displays certificate information only; "
472	              "reading the file successfully does not verify the signature "
473	              "or establish trust.\n";
474	    std::cout << output.str();
475	    return 0;
476	}
