481	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
482	        std::cout << "trustpeek 0.1.0\n";
483	        return 0;
484	    }
485	    if (argc == 3 && std::string_view(argv[1]) == "inspect") {
486	        return inspect_file(argv[2]);
487	    }
488	    print_usage();
489	    return 2;
